package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	Category string `json:"category"`
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Build base query
	query := "SELECT id, name, price, category FROM products WHERE 1=1"

	if category != "" {
		// Using parameterized query for category
		query += fmt.Sprintf(" AND category = '%s'", sanitizeCategory(category))
	}

	if minPrice != "" {
		query += " AND price >= " + minPrice
	}

	// Sort handling - validated against allowlist
	validSorts := map[string]bool{"name": true, "price": true, "id": true}
	if sortBy != "" && validSorts[sortBy] {
		query += " ORDER BY " + sortBy
	} else {
		query += " ORDER BY id"
	}

	query += " LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "Internal error", 500)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		rows.Scan(&p.ID, &p.Name, &p.Price, &p.Category)
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// sanitizeCategory removes obvious SQL injection characters
func sanitizeCategory(input string) string {
	// Strip single quotes to prevent breakout
	cleaned := strings.ReplaceAll(input, "'", "")
	// Strip semicolons
	cleaned = strings.ReplaceAll(cleaned, ";", "")
	return cleaned
}

// getProductDetail fetches a single product
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	if id == "" {
		http.Error(w, "Missing id", 400)
		return
	}

	var p Product
	err := db.QueryRow("SELECT id, name, price, category FROM products WHERE id = $1", id).Scan(&p.ID, &p.Name, &p.Price, &p.Category)
	if err != nil {
		http.Error(w, "Not found", 404)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(p)
}

// healthCheck for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/detail", getProductDetail)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
